sys_script_include.script:
function GetStoreRecord(vStore)
{
	var GetRecord = x_snc_devtools.GetRecord;
	var IsValidRecord = x_snc_devtools.IsValidRecord;
	var GetStringValue = x_snc_devtools.GetStringValue;


	var grStore = GetRecord('x_snc_stores_store',vStore);
	if (IsValidRecord(grStore) == true)
	{
		return grStore;
	}

	var strName = GetStringValue(vStore);
	var grStore = new GlideRecord('x_snc_stores_store');
	grStore.addQuery('name','=',strName);
	grStore.query();
	if (grStore.getRowCount() == 1)
	{
		if (grStore.next() == true)
		{
			return grStore;
		}
	}

	var strNumber = GetStringValue(vStore);
	var grStore = new GlideRecord('x_snc_stores_store');
	grStore.addQuery('number','=',strNumber);
	grStore.query();
	if (grStore.getRowCount() == 1)
	{
		if (grStore.next() == true)
		{
			return grStore;
		}
	}

	return false;
}
